// Replacement for package reflect on the tstst runtime.
//
// Types are the type ids generated by go2types (tables TypeKind, TypeElem,
// TypeFields, ...); a negative id -t stands for a pointer type *t that the
// program never names. A Value is a type and the address of the first heap
// cell holding the value (structs and arrays are flattened into cells; a
// slice, string, map, pointer or interface takes one cell). Values made from
// interfaces are copied into fresh cells; Values reached through pointers,
// slices and fields alias the program's memory.
package reflect

import (
	"errors"
	"strconv"
	"unsafe"
)

type Kind uint

const (
	Invalid Kind = iota
	Bool
	Int
	Int8
	Int16
	Int32
	Int64
	Uint
	Uint8
	Uint16
	Uint32
	Uint64
	Uintptr
	Float32
	Float64
	Complex64
	Complex128
	Array
	Chan
	Func
	Interface
	Map
	Pointer
	Slice
	String
	Struct
	UnsafePointer
)

const Ptr = Pointer

var kindNames = []string{
	Invalid: "invalid", Bool: "bool", Int: "int", Int8: "int8", Int16: "int16", Int32: "int32",
	Int64: "int64", Uint: "uint", Uint8: "uint8", Uint16: "uint16", Uint32: "uint32",
	Uint64: "uint64", Uintptr: "uintptr", Float32: "float32", Float64: "float64",
	Complex64: "complex64", Complex128: "complex128", Array: "array", Chan: "chan",
	Func: "func", Interface: "interface", Map: "map", Pointer: "ptr", Slice: "slice",
	String: "string", Struct: "struct", UnsafePointer: "unsafe.Pointer",
}

func (k Kind) String() string {
	if uint(k) < uint(len(kindNames)) {
		return kindNames[uint(k)]
	}
	return "kind" + strconv.Itoa(int(k))
}

// type tables (go2types intrinsics)
func ifaceTypeID(i any) int
func typeKind(id int) int
func typeElem(id int) int
func typeKey(id int) int
func typeLen(id int) int
func typeCells(id int) int
func typeString(id int) string
func typeName(id int) string
func typePkgPath(id int) string
func typePtrTo(id int) int
func typeImplements(id, iface int) bool
func typeComparable(id int) bool
func typeNumMethod(id int) int
func typeSliceOf(id int) int // []T
func typeSetOf(id int) int   // map[T]struct{}
func typeNumField(id int) int
func typeSize(id int) int
func funcCall(fn any, n int, a0, a1, a2, a3, a4, a5 any) (r0, r1, r2 any) // calls fn with n arguments
func typeAlign(id int) int
func typeNumIn(id int) int
func typeNumOut(id int) int
func typeIn(id, i int) int
func typeOut(id, i int) int
func typeVariadic(id int) bool
func typeField(id, i int) (name string, typ int, offset int, tag string, embedded bool, pkgPath string)

// memory (go2types intrinsics); addresses are cell indices, 0 is nil
func memAlloc(t, n int) int      // n zero values of type t, one after the other
func memLoad(t, p int) any       // the value of (non-interface) type t at p
func memLoadIface(p int) any     // the interface value at p
func memStore(t, p int, x any)   // stores x, whose dynamic type is t, at p
func memStoreIface(p int, x any) // stores the interface value x at p
func memCopy(dst, src, n int)    // copies n cells
func memPtr(p int) int           // the pointer at p
func memSetPtr(p, q int)         // stores pointer q at p
func memSlice(p int) (ptr, len, cap int)
func memSetSlice(p, ptr, len, cap int)
func memRaw(p int) any // the cell at p as is: only compared with nil
func memInt(p int) int64
func memSetInt(p int, v int64)
func memUint(p int) uint64
func memSetUint(p int, v uint64)
func memFloat(p int) float64
func memSetFloat(p int, v float64, f32 bool)
func memString(p int) string
func memSetString(p int, s string)
func memBool(p int) bool
func memSetBool(p int, b bool)
func memBytes(p int) []byte
func memSetBytes(p int, b []byte)
func memUnsafe(p int) unsafe.Pointer
func toUP(p int) unsafe.Pointer   // a cell index as a pointer (0: nil)
func fromUP(p unsafe.Pointer) int // and back
func memIsZero(t, p int) bool
func memEqual(t, p, q int) bool
func mapLen(p int) int
func mapMake(p int)
func mapGet(p, kt, kp, vt, dst int) bool
func mapSet(p, kt, kp, vt, vp int)
func mapDelete(p, kt, kp int)
func mapKeys(p, kt, dst int)

func kindOf(id int) Kind {
	if id < 0 {
		return Pointer
	}
	if id == 0 {
		return Invalid
	}
	return Kind(typeKind(id))
}

func elemOf(id int) int {
	if id < 0 {
		return -id
	}
	return typeElem(id)
}

func cellsOf(id int) int {
	if id < 0 {
		return 1
	}
	return typeCells(id)
}

func ptrTo(id int) int {
	if id > 0 {
		if p := typePtrTo(id); p != 0 {
			return p
		}
		return -id
	}
	panic("reflect: pointer to pointer type " + typeStringOf(id) + " is not supported")
}

func typeStringOf(id int) string {
	if id < 0 {
		return "*" + typeStringOf(-id)
	}
	return typeString(id)
}

// ---------------------------------------------------------------------------
// Types

type rtype struct{ id int }

func toType(id int) Type {
	if id == 0 {
		return nil
	}
	return rtype{id}
}

func idOf(t Type) int {
	if t == nil {
		return 0
	}
	return t.(rtype).id
}

func TypeOf(i any) Type { return toType(ifaceTypeID(i)) }

func TypeFor[T any]() Type {
	return TypeOf((*T)(nil)).Elem()
}

func PointerTo(t Type) Type { return rtype{ptrTo(idOf(t))} }
func PtrTo(t Type) Type     { return PointerTo(t) }

// only the composite types go2types prepared (see reflectNeighbors there)
func SliceOf(t Type) Type {
	id := idOf(t)
	if id > 0 {
		if s := typeSliceOf(id); s != 0 {
			return rtype{s}
		}
	}
	panic("reflect.SliceOf: no type []" + typeStringOf(id) + " in the program")
}

func MapOf(key, elem Type) Type {
	k, e := idOf(key), idOf(elem)
	if k > 0 && kindOf(e) == Struct && typeNumField(e) == 0 {
		if s := typeSetOf(k); s != 0 {
			return rtype{s}
		}
	}
	panic("reflect.MapOf: no type map[" + typeStringOf(k) + "]" + typeStringOf(e) + " in the program")
}

func (t rtype) Kind() Kind     { return kindOf(t.id) }
func (t rtype) String() string { return typeStringOf(t.id) }
func (t rtype) Name() string {
	if t.id < 0 {
		return ""
	}
	return typeName(t.id)
}
func (t rtype) PkgPath() string {
	if t.id < 0 {
		return ""
	}
	return typePkgPath(t.id)
}
func (t rtype) Comparable() bool {
	if t.id < 0 {
		return true
	}
	return typeComparable(t.id)
}

// in bytes, as on linux/amd64
func (t rtype) Size() uintptr   { return uintptr(typeSize(t.id)) }
func (t rtype) Align() int      { return typeAlign(t.id) }
func (t rtype) FieldAlign() int { return typeAlign(t.id) }

func (t rtype) Bits() int {
	switch t.Kind() {
	case Int8, Uint8:
		return 8
	case Int16, Uint16:
		return 16
	case Int32, Uint32, Float32:
		return 32
	case Int, Int64, Uint, Uint64, Uintptr, Float64, Complex64:
		return 64
	case Complex128:
		return 128
	}
	panic("reflect: Bits of non-arithmetic Type " + t.String())
}

func (t rtype) Elem() Type {
	switch t.Kind() {
	case Array, Chan, Map, Pointer, Slice:
		return toType(elemOf(t.id))
	}
	panic("reflect: Elem of invalid type " + t.String())
}

func (t rtype) Key() Type {
	if t.Kind() != Map {
		panic("reflect: Key of non-map type " + t.String())
	}
	return toType(typeKey(t.id))
}

func (t rtype) Len() int {
	if t.Kind() != Array {
		panic("reflect: Len of non-array type " + t.String())
	}
	return typeLen(t.id)
}

func (t rtype) NumMethod() int {
	if t.id < 0 {
		return 0
	}
	return typeNumMethod(t.id)
}

func (t rtype) NumField() int {
	if t.Kind() != Struct {
		panic("reflect: NumField of non-struct type " + t.String())
	}
	return typeNumField(t.id)
}

func (t rtype) Field(i int) StructField {
	if t.Kind() != Struct {
		panic("reflect: Field of non-struct type " + t.String())
	}
	if i < 0 || i >= typeNumField(t.id) {
		panic("reflect: Field index out of bounds")
	}
	name, ft, off, tag, embedded, pkg := typeField(t.id, i)
	return StructField{Name: name, PkgPath: pkg, Type: rtype{ft}, Tag: StructTag(tag),
		Offset: uintptr(off), Index: []int{i}, Anonymous: embedded} // in cells, as addresses
}

func (t rtype) FieldByIndex(index []int) StructField {
	var f StructField
	var cur Type = t
	for k, i := range index {
		if k > 0 && cur.Kind() == Pointer {
			cur = cur.Elem()
		}
		f = cur.Field(i)
		cur = f.Type
	}
	f.Index = append([]int(nil), index...)
	return f
}

func (t rtype) FieldByName(name string) (StructField, bool) {
	return t.FieldByNameFunc(func(s string) bool { return s == name })
}

// breadth first over embedded structs; a name found twice at the same depth
// is ambiguous
func (t rtype) FieldByNameFunc(match func(string) bool) (StructField, bool) {
	type entry struct {
		t     rtype
		index []int
	}
	level := []entry{{t, nil}}
	seen := map[int]bool{}
	for len(level) > 0 {
		var next []entry
		var found StructField
		count := 0
		for _, e := range level {
			if seen[e.t.id] {
				continue
			}
			seen[e.t.id] = true
			n := typeNumField(e.t.id)
			for i := 0; i < n; i++ {
				f := e.t.Field(i)
				idx := append(append([]int(nil), e.index...), i)
				if match(f.Name) {
					count++
					if count == 1 {
						found = f
						found.Index = idx
					}
					continue
				}
				if f.Anonymous {
					ft := f.Type.(rtype)
					if ft.Kind() == Pointer {
						ft = ft.Elem().(rtype)
					}
					if ft.Kind() == Struct {
						next = append(next, entry{ft, idx})
					}
				}
			}
		}
		if count == 1 {
			return found, true
		}
		if count > 1 {
			return StructField{}, false
		}
		level = next
	}
	return StructField{}, false
}

func (t rtype) Implements(u Type) bool {
	if u == nil {
		panic("reflect: nil type passed to Type.Implements")
	}
	if u.Kind() != Interface {
		panic("reflect: non-interface type passed to Type.Implements")
	}
	uid := idOf(u)
	if t.id < 0 {
		return typeNumMethod(uid) == 0
	}
	if t.Kind() == Interface {
		return t.id == uid || typeNumMethod(uid) == 0
	}
	return typeImplements(t.id, uid)
}

func (t rtype) AssignableTo(u Type) bool {
	uid := idOf(u)
	if uid == t.id {
		return true
	}
	if kindOf(uid) == Interface {
		return t.Implements(u)
	}
	return false
}

func isNumber(k Kind) bool { return k >= Int && k <= Float64 }

func (t rtype) ConvertibleTo(u Type) bool {
	k1, k2 := t.Kind(), u.Kind()
	switch {
	case t.id == idOf(u):
		return true
	case isNumber(k1) && isNumber(k2):
		return true
	case k1 == String && k2 == String:
		return true
	case k2 == Interface:
		return t.Implements(u)
	}
	return false
}

func (t rtype) OverflowInt(x int64) bool {
	bits := uint(t.Bits())
	trunc := (x << (64 - bits)) >> (64 - bits)
	return x != trunc
}

func (t rtype) OverflowUint(x uint64) bool {
	bits := uint(t.Bits())
	trunc := (x << (64 - bits)) >> (64 - bits)
	return x != trunc
}

func (t rtype) OverflowFloat(x float64) bool {
	if t.Kind() == Float32 {
		if x < 0 {
			x = -x
		}
		return 3.40282346638528859811704183484516925440e+38 < x && x <= 1.79769313486231570814527423731704356798070e+308
	}
	return false
}

type StructField struct {
	Name      string
	PkgPath   string
	Type      Type
	Tag       StructTag
	Offset    uintptr
	Index     []int
	Anonymous bool
}

func (f StructField) IsExported() bool { return f.PkgPath == "" }

type StructTag string

func (tag StructTag) Get(key string) string {
	v, _ := tag.Lookup(key)
	return v
}

// as in package reflect
func (tag StructTag) Lookup(key string) (value string, ok bool) {
	for tag != "" {
		i := 0
		for i < len(tag) && tag[i] == ' ' {
			i++
		}
		tag = tag[i:]
		if tag == "" {
			break
		}
		i = 0
		for i < len(tag) && tag[i] > ' ' && tag[i] != ':' && tag[i] != '"' && tag[i] != 0x7f {
			i++
		}
		if i == 0 || i+1 >= len(tag) || tag[i] != ':' || tag[i+1] != '"' {
			break
		}
		name := string(tag[:i])
		tag = tag[i+1:]
		i = 1
		for i < len(tag) && tag[i] != '"' {
			if tag[i] == '\\' {
				i++
			}
			i++
		}
		if i >= len(tag) {
			break
		}
		qvalue := string(tag[:i+1])
		tag = tag[i+1:]
		if key == name {
			value, err := strconv.Unquote(qvalue)
			if err != nil {
				break
			}
			return value, true
		}
	}
	return "", false
}

// ---------------------------------------------------------------------------
// Values

type flag uint8

const (
	flagAddr flag = 1 << iota // reached through a pointer: settable
	flagRO                    // reached through an unexported field
)

type Value struct {
	typ int
	// the address of the value: a pointer, so that the collector of the
	// runtime (tstc) sees it when a Value is stored in the heap
	p    unsafe.Pointer
	flag flag
}

func (v Value) ptr() int { return fromUP(v.p) }

type ValueError struct {
	Method string
	Kind   Kind
}

func (e *ValueError) Error() string {
	if e.Kind == Invalid {
		return "reflect: call of " + e.Method + " on zero Value"
	}
	return "reflect: call of " + e.Method + " on " + e.Kind.String() + " Value"
}

func (v Value) must(method string, kinds ...Kind) {
	k := v.Kind()
	for _, want := range kinds {
		if k == want {
			return
		}
	}
	panic(&ValueError{"reflect.Value." + method, k})
}

func ValueOf(i any) Value {
	if i == nil {
		return Value{}
	}
	t := ifaceTypeID(i)
	p := memAlloc(t, 1)
	memStore(t, p, i)
	return Value{typ: t, p: toUP(p)}
}

func New(t Type) Value {
	id := idOf(t)
	if id == 0 {
		panic("reflect: New(nil)")
	}
	q := memAlloc(id, 1)
	pt := ptrTo(id)
	cell := memAlloc(pt, 1)
	memSetPtr(cell, q)
	return Value{typ: pt, p: toUP(cell)}
}

func Zero(t Type) Value {
	id := idOf(t)
	if id == 0 {
		panic("reflect: Zero(nil)")
	}
	return Value{typ: id, p: toUP(memAlloc(id, 1))}
}

func Indirect(v Value) Value {
	if v.Kind() != Pointer {
		return v
	}
	return v.Elem()
}

func MakeSlice(t Type, n, c int) Value {
	id := idOf(t)
	if kindOf(id) != Slice {
		panic("reflect.MakeSlice of non-slice type")
	}
	if n < 0 || c < n {
		panic("reflect.MakeSlice: bad len or cap")
	}
	base := memAlloc(elemOf(id), c)
	cell := memAlloc(id, 1)
	memSetSlice(cell, base, n, c)
	return Value{typ: id, p: toUP(cell)}
}

func MakeMap(t Type) Value { return MakeMapWithSize(t, 0) }

func MakeMapWithSize(t Type, n int) Value {
	id := idOf(t)
	if kindOf(id) != Map {
		panic("reflect.MakeMap of non-map type")
	}
	cell := memAlloc(id, 1)
	mapMake(cell)
	return Value{typ: id, p: toUP(cell)}
}

func (v Value) IsValid() bool { return v.typ != 0 }
func (v Value) Kind() Kind    { return kindOf(v.typ) }

func (v Value) Type() Type {
	if v.typ == 0 {
		panic(&ValueError{"reflect.Value.Type", Invalid})
	}
	return rtype{v.typ}
}

func (v Value) CanAddr() bool      { return v.flag&flagAddr != 0 }
func (v Value) CanSet() bool       { return v.flag&(flagAddr|flagRO) == flagAddr }
func (v Value) CanInterface() bool { return v.typ != 0 }

func (v Value) Interface() any {
	switch v.Kind() {
	case Invalid:
		panic(&ValueError{"reflect.Value.Interface", Invalid})
	case Interface:
		return memLoadIface(v.ptr())
	}
	return memLoad(v.typ, v.ptr())
}

func (v Value) IsNil() bool {
	switch v.Kind() {
	case Slice:
		p, _, _ := memSlice(v.ptr())
		return p == 0
	case Pointer, Map, Chan, Func, UnsafePointer:
		return memRaw(v.ptr()) == nil
	case Interface:
		return memLoadIface(v.ptr()) == nil
	}
	panic(&ValueError{"reflect.Value.IsNil", v.Kind()})
}

func (v Value) IsZero() bool {
	switch v.Kind() {
	case Invalid:
		panic(&ValueError{"reflect.Value.IsZero", Invalid})
	case Interface:
		return memLoadIface(v.ptr()) == nil
	case Slice:
		p, _, _ := memSlice(v.ptr())
		return p == 0
	}
	if v.typ < 0 {
		return memRaw(v.ptr()) == nil
	}
	return memIsZero(v.typ, v.ptr())
}

func (v Value) SetZero() {
	v.mustSet("SetZero")
	z := memAlloc(v.typ, 1)
	memCopy(v.ptr(), z, cellsOf(v.typ))
}

func (v Value) mustSet(method string) {
	if v.flag&flagRO != 0 {
		panic("reflect: reflect.Value." + method + " using value obtained using unexported field")
	}
	if v.flag&flagAddr == 0 {
		panic("reflect: reflect.Value." + method + " using unaddressable value")
	}
}

func (v Value) Elem() Value {
	switch v.Kind() {
	case Pointer:
		q := memPtr(v.ptr())
		if q == 0 {
			return Value{}
		}
		return Value{typ: elemOf(v.typ), p: toUP(q), flag: flagAddr | v.flag&flagRO}
	case Interface:
		x := memLoadIface(v.ptr())
		if x == nil {
			return Value{}
		}
		e := ValueOf(x)
		e.flag |= v.flag & flagRO
		return e
	}
	panic(&ValueError{"reflect.Value.Elem", v.Kind()})
}

func (v Value) NumField() int {
	v.must("NumField", Struct)
	return typeNumField(v.typ)
}

func (v Value) Field(i int) Value {
	v.must("Field", Struct)
	if i < 0 || i >= typeNumField(v.typ) {
		panic("reflect: Field index out of range")
	}
	_, ft, off, _, _, pkg := typeField(v.typ, i)
	f := v.flag
	if pkg != "" {
		f |= flagRO
	}
	return Value{typ: ft, p: toUP(v.ptr() + off), flag: f}
}

func (v Value) FieldByIndex(index []int) Value {
	for k, i := range index {
		if k > 0 && v.Kind() == Pointer {
			if v.IsNil() {
				panic("reflect: indirection through nil pointer to embedded struct")
			}
			v = v.Elem()
		}
		v = v.Field(i)
	}
	return v
}

func (v Value) FieldByIndexErr(index []int) (Value, error) {
	for k, i := range index {
		if k > 0 && v.Kind() == Pointer {
			if v.IsNil() {
				return Value{}, errors.New("reflect: indirection through nil pointer to embedded struct field " + (rtype{elemOf(v.typ)}).Name())
			}
			v = v.Elem()
		}
		v = v.Field(i)
	}
	return v, nil
}

func (v Value) FieldByName(name string) Value {
	if f, ok := (rtype{v.typ}).FieldByName(name); ok {
		return v.FieldByIndex(f.Index)
	}
	return Value{}
}

func (v Value) Len() int {
	switch v.Kind() {
	case Slice:
		_, n, _ := memSlice(v.ptr())
		return n
	case Array:
		return typeLen(v.typ)
	case String:
		return len(memString(v.ptr()))
	case Map:
		return mapLen(v.ptr())
	case Chan:
		return 0
	}
	panic(&ValueError{"reflect.Value.Len", v.Kind()})
}

func (v Value) Cap() int {
	switch v.Kind() {
	case Slice:
		_, _, c := memSlice(v.ptr())
		return c
	case Array:
		return typeLen(v.typ)
	case Chan:
		return 0
	}
	panic(&ValueError{"reflect.Value.Cap", v.Kind()})
}

func (v Value) Index(i int) Value {
	switch v.Kind() {
	case Slice:
		p, n, _ := memSlice(v.ptr())
		if i < 0 || i >= n {
			panic("reflect: slice index out of range")
		}
		e := elemOf(v.typ)
		return Value{typ: e, p: toUP(p + i*cellsOf(e)), flag: flagAddr | v.flag&flagRO}
	case Array:
		if i < 0 || i >= typeLen(v.typ) {
			panic("reflect: array index out of range")
		}
		e := elemOf(v.typ)
		return Value{typ: e, p: toUP(v.ptr() + i*cellsOf(e)), flag: v.flag}
	case String:
		s := memString(v.ptr())
		if i < 0 || i >= len(s) {
			panic("reflect: string index out of range")
		}
		r := ValueOf(s[i])
		r.flag = v.flag & flagRO
		return r
	}
	panic(&ValueError{"reflect.Value.Index", v.Kind()})
}

func (v Value) Slice(i, j int) Value {
	switch v.Kind() {
	case Slice:
		p, _, c := memSlice(v.ptr())
		if i < 0 || j < i || j > c {
			panic("reflect.Value.Slice: slice index out of bounds")
		}
		e := elemOf(v.typ)
		cell := memAlloc(v.typ, 1)
		memSetSlice(cell, p+i*cellsOf(e), j-i, c-i)
		return Value{typ: v.typ, p: toUP(cell), flag: v.flag & flagRO}
	case String:
		s := memString(v.ptr())
		cell := memAlloc(v.typ, 1)
		memSetString(cell, s[i:j])
		return Value{typ: v.typ, p: toUP(cell), flag: v.flag & flagRO}
	}
	panic(&ValueError{"reflect.Value.Slice", v.Kind()})
}

func (v Value) SetLen(n int) {
	v.mustSet("SetLen")
	v.must("SetLen", Slice)
	p, _, c := memSlice(v.ptr())
	if n < 0 || n > c {
		panic("reflect: slice length out of range in SetLen")
	}
	memSetSlice(v.ptr(), p, n, c)
}

func (v Value) Grow(n int) {
	v.mustSet("Grow")
	v.must("Grow", Slice)
	if n < 0 {
		panic("reflect.Value.Grow: negative len")
	}
	p, l, c := memSlice(v.ptr())
	if l+n <= c {
		return
	}
	nc := c * 2
	if nc < l+n {
		nc = l + n
	}
	e := elemOf(v.typ)
	base := memAlloc(e, nc)
	if l > 0 {
		memCopy(base, p, l*cellsOf(e))
	}
	memSetSlice(v.ptr(), base, l, nc)
}

func (v Value) Clear() {
	switch v.Kind() {
	case Map:
		if memRaw(v.ptr()) != nil {
			mapMake(v.ptr())
		}
	case Slice:
		p, l, _ := memSlice(v.ptr())
		e := elemOf(v.typ)
		z := memAlloc(e, l)
		memCopy(p, z, l*cellsOf(e))
	default:
		panic(&ValueError{"reflect.Value.Clear", v.Kind()})
	}
}

func Append(s Value, x ...Value) Value {
	s.must("Append", Slice)
	p, l, c := memSlice(s.ptr())
	e := elemOf(s.typ)
	cell := memAlloc(s.typ, 1)
	memSetSlice(cell, p, l, c)
	r := Value{typ: s.typ, p: toUP(cell), flag: flagAddr}
	r.Grow(len(x))
	np, _, nc := memSlice(cell)
	memSetSlice(cell, np, l+len(x), nc)
	for i, xv := range x {
		Value{typ: e, p: toUP(np + (l+i)*cellsOf(e)), flag: flagAddr}.Set(xv)
	}
	r.flag = 0
	return r
}

func AppendSlice(s, t Value) Value {
	n := t.Len()
	xs := make([]Value, n)
	for i := 0; i < n; i++ {
		xs[i] = t.Index(i)
	}
	return Append(s, xs...)
}

func Copy(dst, src Value) int {
	n := dst.Len()
	if m := src.Len(); m < n {
		n = m
	}
	var dp, sp int
	if dst.Kind() == Array {
		dp = dst.ptr()
	} else {
		dp, _, _ = memSlice(dst.ptr())
	}
	if src.Kind() == Array {
		sp = src.ptr()
	} else if src.Kind() == String {
		s := memString(src.ptr())
		for i := 0; i < n; i++ {
			memSetUint(dp+i, uint64(s[i]))
		}
		return n
	} else {
		sp, _, _ = memSlice(src.ptr())
	}
	memCopy(dp, sp, n*cellsOf(elemOf(dst.typ)))
	return n
}

func (v Value) Addr() Value {
	if v.flag&flagAddr == 0 {
		panic("reflect.Value.Addr of unaddressable value")
	}
	pt := ptrTo(v.typ)
	cell := memAlloc(pt, 1)
	memSetPtr(cell, v.ptr())
	return Value{typ: pt, p: toUP(cell), flag: v.flag & flagRO}
}

func (v Value) Pointer() uintptr {
	switch v.Kind() {
	case Pointer, Map, UnsafePointer:
		return uintptr(memPtr(v.ptr()))
	case Slice:
		p, _, _ := memSlice(v.ptr())
		return uintptr(p)
	case Func, Chan:
		if memRaw(v.ptr()) == nil {
			return 0
		}
		return uintptr(v.ptr())
	}
	panic(&ValueError{"reflect.Value.Pointer", v.Kind()})
}

func (v Value) UnsafePointer() unsafe.Pointer {
	switch v.Kind() {
	case Pointer, Map, UnsafePointer:
		return memUnsafe(v.ptr())
	}
	panic(&ValueError{"reflect.Value.UnsafePointer", v.Kind()})
}

func (v Value) Set(x Value) {
	v.mustSet("Set")
	if !x.IsValid() {
		panic("reflect: call of reflect.Value.Set on zero Value")
	}
	if v.Kind() == Interface && x.typ != v.typ {
		memStoreIface(v.ptr(), x.Interface())
		return
	}
	memCopy(v.ptr(), x.ptr(), cellsOf(v.typ))
}

func (v Value) Int() int64 {
	v.must("Int", Int, Int8, Int16, Int32, Int64)
	return memInt(v.ptr())
}

func (v Value) Uint() uint64 {
	v.must("Uint", Uint, Uint8, Uint16, Uint32, Uint64, Uintptr)
	return memUint(v.ptr())
}

func (v Value) Float() float64 {
	v.must("Float", Float32, Float64)
	return memFloat(v.ptr())
}

func (v Value) Bool() bool {
	v.must("Bool", Bool)
	return memBool(v.ptr())
}

func (v Value) String() string {
	switch v.Kind() {
	case Invalid:
		return "<invalid Value>"
	case String:
		return memString(v.ptr())
	}
	return "<" + typeStringOf(v.typ) + " Value>"
}

func (v Value) Bytes() []byte {
	if v.Kind() == Slice && kindOf(elemOf(v.typ)) == Uint8 {
		return memBytes(v.ptr())
	}
	panic(&ValueError{"reflect.Value.Bytes", v.Kind()})
}

func (v Value) CanInt() bool {
	k := v.Kind()
	return k >= Int && k <= Int64
}

func (v Value) CanUint() bool {
	k := v.Kind()
	return k >= Uint && k <= Uintptr
}

func (v Value) CanFloat() bool {
	k := v.Kind()
	return k == Float32 || k == Float64
}

func (v Value) OverflowInt(x int64) bool     { return rtype{v.typ}.OverflowInt(x) }
func (v Value) OverflowUint(x uint64) bool   { return rtype{v.typ}.OverflowUint(x) }
func (v Value) OverflowFloat(x float64) bool { return rtype{v.typ}.OverflowFloat(x) }

func (v Value) SetInt(x int64) {
	v.mustSet("SetInt")
	switch v.Kind() {
	case Int, Int64:
	case Int8:
		x = int64(int8(x))
	case Int16:
		x = int64(int16(x))
	case Int32:
		x = int64(int32(x))
	default:
		panic(&ValueError{"reflect.Value.SetInt", v.Kind()})
	}
	memSetInt(v.ptr(), x)
}

func (v Value) SetUint(x uint64) {
	v.mustSet("SetUint")
	switch v.Kind() {
	case Uint, Uint64, Uintptr:
	case Uint8:
		x = uint64(uint8(x))
	case Uint16:
		x = uint64(uint16(x))
	case Uint32:
		x = uint64(uint32(x))
	default:
		panic(&ValueError{"reflect.Value.SetUint", v.Kind()})
	}
	memSetUint(v.ptr(), x)
}

func (v Value) SetFloat(x float64) {
	v.mustSet("SetFloat")
	v.must("SetFloat", Float32, Float64)
	memSetFloat(v.ptr(), x, v.Kind() == Float32)
}

func (v Value) SetBool(x bool) {
	v.mustSet("SetBool")
	v.must("SetBool", Bool)
	memSetBool(v.ptr(), x)
}

func (v Value) SetString(x string) {
	v.mustSet("SetString")
	v.must("SetString", String)
	memSetString(v.ptr(), x)
}

func (v Value) SetBytes(x []byte) {
	v.mustSet("SetBytes")
	v.must("SetBytes", Slice)
	memSetBytes(v.ptr(), x)
}

func (v Value) Comparable() bool {
	switch v.Kind() {
	case Invalid:
		return false
	case Interface:
		return v.IsNil() || v.Elem().Comparable()
	}
	return rtype{v.typ}.Comparable()
}

func (v Value) Equal(u Value) bool {
	if v.Kind() == Interface {
		v = v.Elem()
	}
	if u.Kind() == Interface {
		u = u.Elem()
	}
	if !v.IsValid() || !u.IsValid() {
		return v.IsValid() == u.IsValid()
	}
	if v.typ != u.typ {
		return false
	}
	return memEqual(v.typ, v.ptr(), u.ptr())
}

func (v Value) NumMethod() int {
	if v.typ == 0 {
		panic(&ValueError{"reflect.Value.NumMethod", Invalid})
	}
	return rtype{v.typ}.NumMethod()
}

// conversions between numbers, strings and identical layouts
func (v Value) Convert(t Type) Value {
	id := idOf(t)
	if id == v.typ {
		return v
	}
	k1, k2 := v.Kind(), kindOf(id)
	r := Value{typ: id, p: toUP(memAlloc(id, 1))}
	switch {
	case k1 >= Int && k1 <= Int64 && k2 >= Int && k2 <= Int64:
		r.flag = flagAddr
		r.SetInt(v.Int())
	case k1 >= Int && k1 <= Int64 && k2 >= Uint && k2 <= Uintptr:
		r.flag = flagAddr
		r.SetUint(uint64(v.Int()))
	case k1 >= Uint && k1 <= Uintptr && k2 >= Int && k2 <= Int64:
		r.flag = flagAddr
		r.SetInt(int64(v.Uint()))
	case k1 >= Uint && k1 <= Uintptr && k2 >= Uint && k2 <= Uintptr:
		r.flag = flagAddr
		r.SetUint(v.Uint())
	case (k1 == Float32 || k1 == Float64) && (k2 == Float32 || k2 == Float64):
		r.flag = flagAddr
		r.SetFloat(v.Float())
	case k1 >= Int && k1 <= Int64 && (k2 == Float32 || k2 == Float64):
		r.flag = flagAddr
		r.SetFloat(float64(v.Int()))
	case k1 >= Uint && k1 <= Uintptr && (k2 == Float32 || k2 == Float64):
		r.flag = flagAddr
		r.SetFloat(float64(v.Uint()))
	case (k1 == Float32 || k1 == Float64) && k2 >= Int && k2 <= Int64:
		r.flag = flagAddr
		r.SetInt(int64(v.Float()))
	case (k1 == Float32 || k1 == Float64) && k2 >= Uint && k2 <= Uintptr:
		r.flag = flagAddr
		r.SetUint(uint64(v.Float()))
	case k2 == Interface:
		memStoreIface(r.ptr(), v.Interface())
	case cellsOf(id) == cellsOf(v.typ) && k1 == k2:
		memCopy(r.ptr(), v.ptr(), cellsOf(id))
	default:
		panic("reflect.Value.Convert: value of type " + typeStringOf(v.typ) + " cannot be converted to type " + typeStringOf(id))
	}
	r.flag = 0
	return r
}

// a copy of key (or elem) as the map's key type, which may be an interface
func asType(x Value, t int) int {
	if x.typ == t {
		return x.ptr()
	}
	if kindOf(t) == Interface {
		p := memAlloc(t, 1)
		memStoreIface(p, x.Interface())
		return p
	}
	panic("reflect: value of type " + typeStringOf(x.typ) + " is not assignable to type " + typeStringOf(t))
}

func (v Value) MapIndex(key Value) Value {
	v.must("MapIndex", Map)
	kt, vt := typeKey(v.typ), elemOf(v.typ)
	dst := memAlloc(vt, 1)
	if !mapGet(v.ptr(), kt, asType(key, kt), vt, dst) {
		return Value{}
	}
	return Value{typ: vt, p: toUP(dst), flag: v.flag & flagRO}
}

func (v Value) SetMapIndex(key, elem Value) {
	v.must("SetMapIndex", Map)
	if v.flag&flagRO != 0 {
		panic("reflect: reflect.Value.SetMapIndex using value obtained using unexported field")
	}
	kt, vt := typeKey(v.typ), elemOf(v.typ)
	if !elem.IsValid() {
		mapDelete(v.ptr(), kt, asType(key, kt))
		return
	}
	if memRaw(v.ptr()) == nil {
		panic("assignment to entry in nil map")
	}
	mapSet(v.ptr(), kt, asType(key, kt), vt, asType(elem, vt))
}

func (v Value) mapKeyCells() (int, int) {
	kt := typeKey(v.typ)
	n := mapLen(v.ptr())
	dst := memAlloc(kt, n)
	mapKeys(v.ptr(), kt, dst)
	return dst, n
}

func (v Value) MapKeys() []Value {
	v.must("MapKeys", Map)
	kt := typeKey(v.typ)
	dst, n := v.mapKeyCells()
	out := make([]Value, n)
	for i := range out {
		out[i] = Value{typ: kt, p: toUP(dst + i*cellsOf(kt)), flag: v.flag & flagRO}
	}
	return out
}

type MapIter struct {
	m    Value
	keys unsafe.Pointer // the cells of the keys
	n    int
	i    int
}

func (v Value) MapRange() *MapIter {
	if v.Kind() != Map {
		panic(&ValueError{"reflect.Value.MapRange", v.Kind()})
	}
	it := &MapIter{}
	it.Reset(v)
	return it
}

func (it *MapIter) Reset(v Value) {
	it.m = v
	it.i = -1
	it.n = 0
	if v.IsValid() {
		var k int
		k, it.n = v.mapKeyCells()
		it.keys = toUP(k)
	}
}

func (it *MapIter) Next() bool {
	if it.i+1 >= it.n {
		it.i = it.n
		return false
	}
	it.i++
	return true
}

func (it *MapIter) Key() Value {
	if it.i < 0 || it.i >= it.n {
		panic("MapIter.Key called before Next")
	}
	kt := typeKey(it.m.typ)
	return Value{typ: kt, p: toUP(fromUP(it.keys) + it.i*cellsOf(kt)), flag: it.m.flag & flagRO}
}

func (it *MapIter) Value() Value {
	return it.m.MapIndex(it.Key())
}

func (v Value) SetIterKey(it *MapIter)   { v.Set(it.Key()) }
func (v Value) SetIterValue(it *MapIter) { v.Set(it.Value()) }

func TypeAssert[T any](v Value) (T, bool) {
	x, ok := v.Interface().(T)
	return x, ok
}

// ---------------------------------------------------------------------------
// DeepEqual, as in package reflect

type visit struct {
	a, b, typ int
}

func DeepEqual(x, y any) bool {
	if x == nil || y == nil {
		return x == y
	}
	v1, v2 := ValueOf(x), ValueOf(y)
	if v1.typ != v2.typ {
		return false
	}
	return deepValueEqual(v1, v2, map[visit]bool{})
}

func deepValueEqual(v1, v2 Value, visited map[visit]bool) bool {
	if !v1.IsValid() || !v2.IsValid() {
		return v1.IsValid() == v2.IsValid()
	}
	if v1.typ != v2.typ {
		return false
	}
	switch v1.Kind() {
	case Map, Slice, Pointer, Interface:
		k := visit{v1.ptr(), v2.ptr(), v1.typ}
		if visited[k] {
			return true
		}
		visited[k] = true
	}
	switch v1.Kind() {
	case Array:
		for i := 0; i < v1.Len(); i++ {
			if !deepValueEqual(v1.Index(i), v2.Index(i), visited) {
				return false
			}
		}
		return true
	case Slice:
		if v1.IsNil() != v2.IsNil() || v1.Len() != v2.Len() {
			return false
		}
		if v1.Pointer() == v2.Pointer() {
			return true
		}
		for i := 0; i < v1.Len(); i++ {
			if !deepValueEqual(v1.Index(i), v2.Index(i), visited) {
				return false
			}
		}
		return true
	case Interface:
		if v1.IsNil() || v2.IsNil() {
			return v1.IsNil() == v2.IsNil()
		}
		return deepValueEqual(v1.Elem(), v2.Elem(), visited)
	case Pointer:
		if v1.Pointer() == v2.Pointer() {
			return true
		}
		return deepValueEqual(v1.Elem(), v2.Elem(), visited)
	case Struct:
		for i, n := 0, v1.NumField(); i < n; i++ {
			if !deepValueEqual(v1.Field(i), v2.Field(i), visited) {
				return false
			}
		}
		return true
	case Map:
		if v1.IsNil() != v2.IsNil() || v1.Len() != v2.Len() {
			return false
		}
		if v1.Pointer() == v2.Pointer() {
			return true
		}
		for _, k := range v1.MapKeys() {
			val1 := v1.MapIndex(k)
			val2 := v2.MapIndex(k)
			if !val1.IsValid() || !val2.IsValid() || !deepValueEqual(val1, val2, visited) {
				return false
			}
		}
		return true
	case Func:
		return v1.IsNil() && v2.IsNil()
	case Int, Int8, Int16, Int32, Int64:
		return v1.Int() == v2.Int()
	case Uint, Uint8, Uint16, Uint32, Uint64, Uintptr:
		return v1.Uint() == v2.Uint()
	case String:
		return v1.String() == v2.String()
	case Bool:
		return v1.Bool() == v2.Bool()
	case Float32, Float64:
		return v1.Float() == v2.Float()
	}
	return memEqual(v1.typ, v1.ptr(), v2.ptr())
}

func Swapper(slice any) func(i, j int) {
	v := ValueOf(slice)
	if v.Kind() != Slice {
		panic(&ValueError{"Swapper", v.Kind()})
	}
	p, _, _ := memSlice(v.ptr())
	e := elemOf(v.typ)
	n := cellsOf(e)
	tmp := memAlloc(e, 1)
	return func(i, j int) {
		memCopy(tmp, p+i*n, n)
		memCopy(p+i*n, p+j*n, n)
		memCopy(p+j*n, tmp, n)
	}
}

// Methods are not available through reflection (calling them would need
// reflect.Value.Call): MethodByName reports none, so go-cmp and similar
// packages compare values structurally.
func (t rtype) MethodByName(name string) (Method, bool) { return Method{}, false }

func (t rtype) NumIn() int {
	t.mustFunc("NumIn")
	return typeNumIn(t.id)
}

func (t rtype) NumOut() int {
	t.mustFunc("NumOut")
	return typeNumOut(t.id)
}

func (t rtype) In(i int) Type {
	t.mustFunc("In")
	if i < 0 || i >= typeNumIn(t.id) {
		panic("reflect: Function index out of range")
	}
	return rtype{typeIn(t.id, i)}
}

func (t rtype) Out(i int) Type {
	t.mustFunc("Out")
	if i < 0 || i >= typeNumOut(t.id) {
		panic("reflect: Function index out of range")
	}
	return rtype{typeOut(t.id, i)}
}

func (t rtype) IsVariadic() bool {
	t.mustFunc("IsVariadic")
	return typeVariadic(t.id)
}

func (t rtype) mustFunc(method string) {
	if t.Kind() != Func {
		panic("reflect: " + method + " of non-func type " + t.String())
	}
}

// UnsafeAddr is the cell address of the variable (go-cmp reads unexported
// fields at it plus their offsets, which count cells)
func (v Value) UnsafeAddr() uintptr {
	if v.flag&flagAddr == 0 {
		panic("reflect: reflect.Value.UnsafeAddr of unaddressable value")
	}
	return uintptr(v.ptr())
}

// NewAt is a pointer to the variable of type t at p
func NewAt(t Type, p unsafe.Pointer) Value {
	pt := ptrTo(idOf(t))
	cell := memAlloc(pt, 1)
	memSetPtr(cell, int(uintptr(p)))
	return Value{typ: pt, p: toUP(cell)}
}

// Call: up to 6 arguments and 3 results
func (v Value) Call(in []Value) []Value {
	if v.Kind() != Func {
		panic(&ValueError{"reflect.Value.Call", v.Kind()})
	}
	ft := v.typ
	nin := typeNumIn(ft)
	if typeVariadic(ft) && len(in) >= nin-1 {
		st := typeIn(ft, nin-1)
		rest := in[nin-1:]
		sl := MakeSlice(rtype{st}, len(rest), len(rest))
		for i, x := range rest {
			sl.Index(i).Set(x)
		}
		in = append(in[:nin-1:nin-1], sl)
	}
	if len(in) != nin {
		panic("reflect: Call with the wrong number of arguments")
	}
	nout := typeNumOut(ft)
	if nin > 6 || nout > 3 {
		panic("reflect: Call of a function with more than 6 parameters or 3 results is not supported")
	}
	var a [6]any
	for i, x := range in {
		a[i] = x.Interface()
	}
	r0, r1, r2 := funcCall(v.Interface(), nin, a[0], a[1], a[2], a[3], a[4], a[5])
	rs := [3]any{r0, r1, r2}
	out := make([]Value, nout)
	for i := range out {
		t := typeOut(ft, i)
		cell := memAlloc(t, 1)
		if kindOf(t) == Interface {
			memStoreIface(cell, rs[i])
		} else if rs[i] != nil {
			memStore(t, cell, rs[i])
		}
		out[i] = Value{typ: t, p: toUP(cell)}
	}
	return out
}

// no methods are known by name (as Type.MethodByName)
func (v Value) MethodByName(name string) Value { return Value{} }
